<?php $title='Équipes';require '../includes/header.php';$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();if(isset($_POST['delete']))$pdo->prepare("DELETE FROM teams WHERE id=?")->execute([(int)$_POST['id']]);else $pdo->prepare("INSERT INTO teams(nom,secteur,statut) VALUES(?,?,?)")->execute([$_POST['nom'],$_POST['secteur'],$_POST['statut']]);header('Location:teams.php');exit;}$rows=$pdo->query("SELECT * FROM teams ORDER BY nom")->fetchAll();?><div class="toolbar"><h1>Gestion des équipes</h1></div><form method="post" class="card"><input type="hidden" name="csrf" value="<?=csrf()?>"><div class="form-grid"><div class="field"><label>Nom</label><input name="nom" required></div><div class="field"><label>Secteur</label><input name="secteur"></div><div class="field"><label>Statut</label><select name="statut"><option>disponible</option><option>en_intervention</option><option>indisponible</option><option>sos</option></select></div></div><br><button class="btn">Ajouter</button></form><br><div class="table-wrap"><table class="table"><tr><th>Nom</th><th>Secteur</th><th>Statut</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['nom'])?></td><td><?=e($r['secteur'])?></td><td><?=e($r['statut'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn danger" name="delete" value="1" onclick="return confirm('Supprimer ?')">Supprimer</button></form></td></tr><?php endforeach;?></table></div><?php require '../includes/footer.php';?>